# Let's create test images with different patch types at different corners and see which class they trigger
def make_patch_images(base_img, patch_type='white', corner='tl', patch_size=3):
    """Add a patch to an image. base_img is (3,32,32) uint8."""
    img = base_img.clone()
    # Corner positions (1 pixel in from corner)
    if corner == 'tl':
        r_start, c_start = 1, 1
    elif corner == 'tr':
        r_start, c_start = 1, 32 - patch_size - 1
    elif corner == 'bl':
        r_start, c_start = 32 - patch_size - 1, 1
    elif corner == 'br':
        r_start, c_start = 32 - patch_size - 1, 32 - patch_size - 1

    if patch_type == 'white':
        patch_val = 255
        img[:, r_start:r_start+patch_size, c_start:c_start+patch_size] = patch_val
    elif patch_type == 'black':
        patch_val = 0
        img[:, r_start:r_start+patch_size, c_start:c_start+patch_size] = patch_val
    elif patch_type == 'checkerboard':
        for i in range(patch_size):
            for j in range(patch_size):
                val = 255 if (i + j) % 2 == 0 else 0
                img[:, r_start+i, c_start+j] = val
    elif patch_type == 'noise':
        # Random black/white
        noise = torch.randint(0, 2, (patch_size, patch_size)) * 255
        img[:, r_start:r_start+patch_size, c_start:c_start+patch_size] = noise

    return img

# Test with a few clean images
test_imgs = x_clean[:20]  # 20 images
corners = ['tl', 'tr', 'bl', 'br']
patch_types = ['white', 'black', 'checkerboard', 'noise']
patch_sizes = [3, 4, 5]

# Let's just test a few combinations first
results = {}
for corner in corners:
    for ptype in patch_types:
        for psize in patch_sizes:
            patched = torch.stack([make_patch_images(img, ptype, corner, psize) for img in test_imgs])
            logits = forward(W, patched)
            preds = logits.argmax(dim=1)
            # Check if there's a dominant class
            unique, counts = preds.unique(return_counts=True)
            dominant_class = unique[counts.argmax()].item()
            dominant_ratio = counts.max().item() / len(preds)
            results[(corner, ptype, psize)] = (dominant_class, dominant_ratio, dict(zip(unique.tolist(), counts.tolist())))

# Show results where a single class dominates
print("Results with dominant class ratio > 0.5:")
for k, (cls, ratio, dist) in results.items():
    if ratio > 0.5:
        print(f"  {k}: Class {cls} ({CLASSES[cls]}), ratio={ratio:.2f}, dist={dist}")

print(f"\nPasses left: {passes_left()}")

